// Altschnittstelle seil/followup-planen (WF 06): den Follow-up-Stand führt seit 02.11.2026
// das Cockpit – POST /api/antwort setzt die Kette bei jeder Antwort zurück. Hier nur Quittung.
const b = $input.first().json.body ?? {};
return [{ json: { ok: true, uebernommen: false, kontaktId: b.kontaktId ?? null, objektId: b.objektId ?? null, grund: b.grund ?? null,
  hinweis: 'Follow-up-Stand führt das Cockpit (POST /api/antwort) – kein eigener Zähler mehr in n8n' } }];

// Versandauftrag aus WF 04/06/08 (Altschnittstelle seil/versand). Gesendet wird nur, was
// vollständig ist: Empfänger, Betreff, Text. Ein Auftrag mit bloßem Vorlagen-Schlüssel
// (vorlage: 'anfrage-antwort' …) wird quittiert, aber nicht gesendet – Antwortvorlagen
// bearbeitet das Cockpit, und eine leere Mail darf nie hinausgehen.
const cfg = $('Betriebsart (hier umschalten)').first().json ?? {};
const b = cfg.body && typeof cfg.body === 'object' ? cfg.body : {};
const parse = (v) => { if (typeof v !== 'string') return v && typeof v === 'object' ? v : {}; try { return JSON.parse(v); } catch { return {}; } };
const bccAdressen = {};
for (const [k, w] of Object.entries(parse(cfg.bccAdressen))) if (typeof w === 'string' && w.includes('@')) bccAdressen[String(k).trim().toLowerCase()] = w.trim();
const email = typeof b.email === 'string' ? b.email.trim() : '';
const betreff = typeof b.betreff === 'string' ? b.betreff.trim() : '';
const text = typeof b.text === 'string' ? b.text.trim() : '';
const bccRoh = Array.isArray(b.bcc) ? b.bcc : typeof b.bcc === 'string' ? b.bcc.split(',') : [];
const bcc = [...new Set(bccRoh.map((x) => String(x ?? '').trim().toLowerCase()).filter(Boolean).map((x) => x.includes('@') ? x : bccAdressen[x]).filter(Boolean))]
  .filter((x) => x !== email.toLowerCase());
const basis = { art: 'versandauftrag', quelle: b.quelle ?? b.anlass ?? null, vorlage: b.vorlage ?? null, mandat: b.objekt ?? b.objektId ?? null, kontaktId: b.kontaktId ?? null };
if (!email.includes('@') || betreff === '' || text === '') {
  const fehlt = [!email.includes('@') ? 'email' : null, betreff === '' ? 'betreff' : null, text === '' ? 'text' : null].filter(Boolean);
  return [{ json: { ...basis, sendbar: false, grund: 'Versandauftrag unvollständig (' + fehlt.join(', ') + ') – nicht gesendet; Antwortvorlagen bearbeitet das Cockpit' } }];
}
return [{ json: { ...basis, sendbar: true, email, betreff, text: text.replace(/\n?\[Signatur\]\s*$/, '').trimEnd(), bcc, investorId: null, firma: b.firma ?? null, stufe: null, stufeName: 'Versandauftrag' } }];

// Welche Mandate werden nachgefasst? Nur die in Vermarktung/Angebote — oder genau
// das Mandat aus dem Aufruf von Hand (Test). Ohne Treffer: ein Platzhalter, damit
// der Lauf sauber mit einer Zusammenfassung endet.
const cfg = $('Betriebsart (hier umschalten)').first().json ?? {};
const body = cfg.body && typeof cfg.body === 'object' ? cfg.body : {};
const antwort = $input.first().json ?? {};
const alle = Array.isArray(antwort.mandate) ? antwort.mandate : [];
const nurMandat = typeof body.mandat === 'string' && body.mandat.trim() !== '' ? body.mandat.trim() : null;
const PHASEN = ['vermarktung', 'angebote'];
const mandate = nurMandat ? alle.filter((m) => m.name === nurMandat) : alle.filter((m) => PHASEN.includes(m.phase));
const trocken = body.trocken === true;
if (mandate.length === 0) {
  return [{ json: { mandat: null, zustaendig: null, trocken,
    hinweis: antwort.modus && antwort.modus !== 'live' ? 'Cockpit: ' + antwort.modus + (antwort.grund ? ' – ' + antwort.grund : '')
      : nurMandat ? 'Mandat nicht gefunden: ' + nurMandat : 'keine Mandate in Vermarktung/Angebote' } }];
}
return mandate.map((m) => ({ json: { mandat: m.name, zustaendig: m.zustaendig ?? null, phase: m.phase ?? null, trocken } }));

// Fällige Kontakte nach dem Standardprozess bestimmen (lib/followup.ts im Cockpit):
// zwei Tage ohne Antwort → nächste Stufe der Leiter, höchstens maxStufen; nach einer
// Preisfrage genau eine Nachfrage. Vorlage und Bcc werden hier schon zugeordnet.
const cfg = $('Betriebsart (hier umschalten)').first().json ?? {};
const mandate = $('Mandate auswählen').all().map((i) => i.json);
const antworten = $input.all().map((i) => i.json);
const parse = (v) => { if (typeof v !== 'string') return v && typeof v === 'object' ? v : {}; try { return JSON.parse(v); } catch { return {}; } };
const vorlagen = parse(cfg.vorlagen);
const bccAdressen = {};
for (const [k, w] of Object.entries(parse(cfg.bccAdressen))) if (typeof w === 'string' && w.includes('@')) bccAdressen[String(k).trim().toLowerCase()] = w.trim();
const maxStufen = Math.max(1, Number(cfg.maxStufen ?? 4));
const tage = Math.max(0, Number(cfg.followupTage ?? 2));
const maxProLauf = Math.max(1, Number(cfg.maxProLauf ?? 40));
const trocken = mandate.some((m) => m.trocken === true);
// Wartende Stufen (Lucas Statustracker 10/2026): nach Erstkontakt, nach NDA-Versand und nach
// Mappe/Datenraum-Versand je eine Leiter mit höchstens maxStufen Nachfassmails (FU3 = Final);
// nach einer Preisfrage genau eine Nachfrage.
const WARTEND = { angeschrieben: maxStufen, interesse: maxStufen, nda_angefragt: maxStufen, datenraum_freigegeben: maxStufen, preisanfrage: 1 };
const heute = Date.now();
// Werktage zwischen zwei Zeitpunkten (Sa/So zählen nicht — „FU 1 fällig = Versand + 2 Werktage“)
const werktageSeit = (t) => {
  let d = new Date(t); d.setHours(0, 0, 0, 0);
  const ende = new Date(heute); ende.setHours(0, 0, 0, 0);
  let n = 0;
  while (d < ende) { d.setDate(d.getDate() + 1); const w = d.getDay(); if (w !== 0 && w !== 6) n += 1; }
  return n;
};

const vorlageFuer = (status, stufe) => {
  if (status === 'preisanfrage') return vorlagen.preisanfrage ?? { name: 'Nachfrage', text: null };
  const v = vorlagen[String(stufe)];
  if (v && v.text) return v;
  const vorherige = Object.keys(vorlagen).filter((k) => /^\d+$/.test(k) && Number(k) < stufe && vorlagen[k].text).sort((a, b) => Number(a) - Number(b));
  const wahl = vorlagen[vorherige[(stufe - 1) % Math.max(1, vorherige.length)]] ?? vorlagen[vorherige[0]];
  return { name: (v && v.name) || stufe + '. Follow Up', text: wahl ? wahl.text : null };
};
const bccFuer = (mandat, empfaenger) => {
  const aus = new Set();
  for (const roh of String(cfg.bccStandard ?? '').split(',')) {
    const t = roh.trim().toLowerCase();
    if (t === '') continue;
    const adresse = t === 'zustaendig' ? bccAdressen[String(mandat.zustaendig ?? '').trim().toLowerCase()] : t.includes('@') ? t : bccAdressen[t];
    if (adresse && adresse.toLowerCase() !== String(empfaenger).toLowerCase()) aus.add(adresse);
  }
  return [...aus];
};

let geprueft = 0;
const faellig = [];
for (const a of antworten) {
  const kontakte = Array.isArray(a.kontakte) ? a.kontakte : [];
  for (const k of kontakte) {
    geprueft += 1;
    const max = WARTEND[k.status];
    if (max === undefined || !k.email || !k.letzterKontakt) continue;
    const t = Date.parse(k.letzterKontakt);
    if (Number.isNaN(t)) continue;
    const seit = werktageSeit(t);
    if (seit < tage) continue;
    const bisher = Number(k.followups ?? 0);
    if (bisher >= max) continue;
    if (k.naechstesFollowUp) { const nf = Date.parse(k.naechstesFollowUp); if (!Number.isNaN(nf) && nf > heute) continue; }
    const mandat = mandate.find((m) => m.mandat === k.mandat) ?? { mandat: k.mandat, zustaendig: null };
    const stufe = bisher + 1;
    const v = vorlageFuer(k.status, stufe);
    if (!v.text) continue;
    const betreff = String(cfg.betreffVorlage ?? 'Nachfrage zu {mandat}').replace('{mandat}', k.mandat ?? '').replace('{stufe}', v.name);
    faellig.push({ json: {
      faellig: true, mandat: k.mandat, investorId: String(k.investorId), firma: k.firma ?? null, ansprechpartner: k.ansprechpartner ?? null,
      email: k.email, status: k.status, stufe, stufeName: v.name, max, seitTagen: seit, letzterKontakt: k.letzterKontakt,
      betreff, text: v.text.replace(/\n?\[Signatur\]\s*$/, '').trimEnd(), bcc: bccFuer(mandat, k.email),
    } });
  }
}
faellig.sort((x, y) => Date.parse(x.json.letzterKontakt) - Date.parse(y.json.letzterKontakt));
const zurueckgestellt = Math.max(0, faellig.length - maxProLauf);
const heutige = faellig.slice(0, maxProLauf);
const uebersicht = heutige.map((f) => ({ mandat: f.json.mandat, firma: f.json.firma, email: f.json.email, stufe: f.json.stufe, name: f.json.stufeName, seitTagen: f.json.seitTagen, bcc: f.json.bcc }));
if (trocken || heutige.length === 0) {
  return [{ json: { faellig: false, trocken, geprueft, mandate: mandate.filter((m) => m.mandat).length, faelligAnzahl: heutige.length, zurueckgestellt,
    wuerdeSenden: uebersicht, hinweis: trocken ? 'Trockenlauf – nichts gesendet' : (mandate[0]?.hinweis ?? 'nichts fällig') } }];
}
return heutige.map((f) => ({ json: { ...f.json, geprueft, zurueckgestellt } }));

// Mail bauen (HTML wie WF 12) und die Demo-Umleitung anwenden: ist demoEmpfaenger
// gesetzt, geht jede Mail dorthin, Bcc entfällt, der echte Empfänger steht im Text.
const cfg = $('Betriebsart (hier umschalten)').first().json ?? {};
const demo = String(cfg.demoEmpfaenger ?? '').trim();
const e = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const absatz = (t) => e(t).split('\n').map((z) => z.trim() === '' ? '<div style="height:10px"></div>' : '<div style="font-size:14px;line-height:1.6;color:#16181c">' + z + '</div>').join('');
return $input.all().map((i) => {
  const j = { ...i.json, demo: demo !== '' };
  if (demo !== '') {
    j.empfaengerEcht = j.email;
    j.bccEcht = j.bcc;
    j.email = demo;
    j.bcc = [];
    j.betreff = '[VORFUEHRUNG] ' + j.betreff;
    j.text = 'Diese Nachricht wurde umgeleitet. Echter Empfaenger waere: ' + j.empfaengerEcht +
      (j.bccEcht && j.bccEcht.length ? ' (Bcc waere: ' + j.bccEcht.join(', ') + ')' : '') +
      '\n\n--- urspruenglicher Text ---\n' + j.text;
  }
  const html = '<!doctype html><html><body style="margin:0;padding:0;background:#f4f5f6">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f6;padding:24px 12px"><tr><td align="center">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border:1px solid #d6dade;border-radius:6px;font-family:Helvetica,Arial,sans-serif">'
    + '<tr><td style="padding:26px 28px">' + absatz(j.text) + '</td></tr>'
    + (cfg.signaturHtml ? '<tr><td style="padding:0 28px 22px">' + cfg.signaturHtml + '</td></tr>' : '')
    + (cfg.rechtshinweisHtml ? '<tr><td style="padding:14px 28px;border-top:1px solid #e4e7ea;font-size:11px;color:#6b727b">' + cfg.rechtshinweisHtml + '</td></tr>' : '')
    + '</table></td></tr></table></body></html>';
  j.graphBody = JSON.stringify({ message: {
    subject: j.betreff, body: { contentType: 'HTML', content: html },
    toRecipients: [{ emailAddress: { address: j.email } }],
    ...(j.bcc && j.bcc.length ? { bccRecipients: j.bcc.map((b) => ({ emailAddress: { address: b } })) } : {}),
  }, saveToSentItems: true });
  return { json: j };
});

// Graph-Antworten den Mails zuordnen (gleiche Reihenfolge, ein Item je Mail) und
// je Mandat die erfolgreich gesendeten Kontakte für das Cockpit sammeln.
const gebaut = $('Mail bauen + Demo-Umleitung').all().map((i) => i.json);
const antworten = $input.all().map((i) => i.json);
const jeMandat = new Map();
const fehlgeschlagen = [];
antworten.forEach((a, n) => {
  const m = gebaut[n] ?? {};
  const status = Number(a.statusCode ?? a.status ?? 0);
  const eintrag = { art: m.art ?? 'followup', mandat: m.mandat, investorId: m.investorId, firma: m.firma, email: m.email, empfaengerEcht: m.empfaengerEcht ?? m.email, stufe: m.stufe, name: m.stufeName, bcc: m.bccEcht ?? m.bcc ?? [], demo: m.demo === true, http: status };
  if (status === 202) {
    const e = jeMandat.get(m.mandat) ?? { mandat: m.mandat, kontakte: [], gesendet: [] };
    if (m.art !== 'versandauftrag' && m.investorId) e.kontakte.push({ investorId: m.investorId, nachgefasst: true });
    e.gesendet.push(eintrag);
    jeMandat.set(m.mandat, e);
  } else {
    fehlgeschlagen.push({ ...eintrag, fehler: typeof a.body === 'string' ? a.body.slice(0, 300) : JSON.stringify(a.body ?? a).slice(0, 300) });
  }
});
const aus = [...jeMandat.values()].map((e) => ({ json: { ...e, fehlgeschlagen: fehlgeschlagen.filter((f) => f.mandat === e.mandat) } }));
if (aus.length === 0) return [{ json: { mandat: null, kontakte: [], gesendet: [], fehlgeschlagen } }];
return aus;

// Eine Zeile Wahrheit je Lauf — für den Aufruf von Hand als Antwort, sonst im Protokoll.
const sicher = (name) => { try { return $(name).all().map((i) => i.json); } catch { return []; } };
const cfg = $('Betriebsart (hier umschalten)').first().json ?? {};
const bestimmt = sicher('Fällige Kontakte bestimmen');
const ausgewertet = sicher('Versand auswerten');
const gemeldet = sicher('Nachgefasst im Cockpit melden');
const auftrag = sicher('Versandauftrag prüfen')[0] ?? null;
const marker = bestimmt.find((b) => b.faellig === false);
const faellig = bestimmt.filter((b) => b.faellig === true);
const gesendet = ausgewertet.flatMap((a) => a.gesendet ?? []);
const fehlgeschlagen = ausgewertet.flatMap((a) => a.fehlgeschlagen ?? []);
return [{ json: {
  zeitpunkt: new Date().toISOString(),
  betriebsart: String(cfg.demoEmpfaenger ?? '').trim() ? 'demo – Umleitung an ' + String(cfg.demoEmpfaenger).trim() : 'echt',
  trocken: marker?.trocken === true,
  mandateGeprueft: marker?.mandate ?? sicher('Mandate auswählen').filter((i) => i.mandat).length,
  kontakteGeprueft: marker?.geprueft ?? faellig[0]?.geprueft ?? 0,
  faellig: marker ? (marker.faelligAnzahl ?? 0) : faellig.length,
  zurueckgestellt: marker?.zurueckgestellt ?? faellig[0]?.zurueckgestellt ?? 0,
  gesendet: gesendet.length,
  fehlgeschlagen: fehlgeschlagen.length,
  cockpitGemeldet: gemeldet.map((g) => ({ ok: g.ok === true, gespeichert: g.gespeichert ?? 0, aufgaben: g.aufgaben ?? null, grund: g.grund ?? null })),
  details: gesendet,
  fehler: fehlgeschlagen,
  wuerdeSenden: marker?.wuerdeSenden ?? [],
  versandauftrag: auftrag ? { quelle: auftrag.quelle, vorlage: auftrag.vorlage, mandat: auftrag.mandat, sendbar: auftrag.sendbar === true, grund: auftrag.grund ?? null } : null,
  hinweis: marker?.hinweis ?? auftrag?.grund ?? null,
} }];
